#[test]
fn screen_release_relinquishes_loaded_underlay_callback_owners() {
    for live in [false, true] {
        let mut p = Pair::new(live, [true, true], "");
        p.load();
        p.script(r#"
            local u=TOP:GetChild('Underlay')
            local a=u:GetChild('NoteFieldContainerP1');local b=u:GetChild('SongMeter');local c=u:GetChild('DangerP2')
            assert(a and b and c);WEAK=setmetatable({a,b,c},{__mode='v'})
            root=nil;TOP=nil;__songlua_top_screen=nil;__songlua_top_screen_player_1=nil;__songlua_top_screen_player_2=nil
            GetPlayerAF=nil;MusicRateDisplay=nil;dispP1=nil;dispP2=nil
        "#);
        assert!(p.rust.release_actor_scene(p.scene).unwrap());
        eprintln!("underlay release live={live}");
        p.rust
            .vm_mut()
            .execute(
                &compile_named(
                    br#"
            collectgarbage('collect');collectgarbage('collect')
            local function owner_path(target)
                local queue={{_G,'_G'},{debug.getregistry(),'registry'}};local seen={};local index=1
                local function enqueue(v,path)
                    if type(v)=='table' or type(v)=='function' then queue[#queue+1]={v,path} end
                end
                while index<=#queue and index<30000 do
                    local v,path=unpack(queue[index]);index=index+1
                    if v==target then return path end
                    if not seen[v] then
                        seen[v]=true
                        if type(v)=='table' then
                            local mt=getmetatable(v);local mode=type(mt)=='table' and rawget(mt,'__mode') or ''
                            if type(mode)~='string' then mode='' end
                            for k,child in next,v do
                                if k~='WEAK' and not string.find(mode,'v',1,true) then enqueue(child,path..'.'..tostring(k))end
                                if not string.find(mode,'k',1,true) then enqueue(k,path..'.<key>')end
                            end
                            enqueue(mt,path..'.<metatable>')
                        else
                            enqueue(getfenv(v),path..'.<environment>')
                            for n=1,100 do local name,value=debug.getupvalue(v,n);if not name then break end;enqueue(value,path..'.<upvalue:'..name..'>')end
                        end
                    end
                end
                return 'not found among '..tostring(index)..' reachable references'
            end
            for i=1,3 do
                if WEAK[i] then error('retained underlay actor '..i..': '..owner_path(WEAK[i]))end
            end
        "#,
                    b"=underlay release",
                )
                .unwrap(),
            )
            .unwrap();
    }
}

